 public ReaderApp(string folder,string[] args){arguments=args;store=new Store(folder);engine=new Engine(store);aiService=new AiService(store);aiService.Changed+=()=>UI(Push);engine.Discovered+=ids=>UI(()=>QueueAi(ids));engine.StartupSummary+=count=>UI(()=>{startupCount+=count;summaryDue=Data.Now()+3000;});var menu=new ContextMenuStrip();menu.Items.Add("打开拾讯",null,delegate{ShowReader();});menu.Items.Add("立即同步",null,async delegate{await engine.Run(true);});menu.Items.Add("暂停通知15分钟",null,delegate{pauseUntil=Data.Now()+900000;});menu.Items.Add("退出",null,delegate{ExitThread();});tray=new NotifyIcon{Visible=true,Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath),Text="拾讯 · RSS订阅",ContextMenuStrip=menu};tray.MouseClick+=delegate(object s,MouseEventArgs e){if(e.Button==MouseButtons.Left)ShowReader();};engine.Changed+=()=>UI(Push);engine.Arrived+=articles=>UI(()=>Notify(articles,false));Microsoft.Win32.SystemEvents.SessionSwitch+=OnSession;timer.Interval=1500;timer.Tick+=OnTick;timer.Start();File.WriteAllText(Path.Combine(folder,"app.pid"),System.Diagnostics.Process.GetCurrentProcess().Id.ToString());store.Clean();ShowReader();int migrate=Array.IndexOf(args,"--migrate");if(migrate>=0&&migrate+1<args.Length)Migrate(args[migrate+1]);}
 int startupCount;double summaryDue;
 void ShowStartupSummary(){if(startupCount==0||engine.Busy||Data.Now()<summaryDue)return;Preferences prefs;lock(store.Gate)prefs=Data.Clone(store.State.settings);if(prefs.notification=="off"||Rules.Quiet(prefs,DateTime.Now)||!Popup.Allowed())return;int count=startupCount;startupCount=0;var summary=new StartupPopup(count,prefs.duration,()=>ShowReader());var area=Screen.FromPoint(Cursor.Position).WorkingArea;summary.StartPosition=FormStartPosition.Manual;summary.Location=new Point(area.Right-summary.Width-20,area.Bottom-summary.Height-20);summary.Show();}
