 async void ShowReader(){if(window!=null){window.Show();window.WindowState=FormWindowState.Normal;window.Activate();Push();return;}if(showing)return;showing=true;window=new Form{Text="拾讯 · RSS订阅",Size=new Size(1440,940),MinimumSize=new Size(760,600),StartPosition=FormStartPosition.CenterScreen,Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath)};web=new WebView2{Dock=DockStyle.Fill,DefaultBackgroundColor=Color.FromArgb(247,248,245)};window.Controls.Add(web);window.FormClosing+=delegate(object s,FormClosingEventArgs e){if(!exiting){e.Cancel=true;window.Hide();}};window.Show();try{var env=await CoreWebView2Environment.CreateAsync(null,Path.Combine(store.Folder,"webview"),new CoreWebView2EnvironmentOptions("--disk-cache-size=10485760 --disable-gpu-shader-disk-cache"));await web.EnsureCoreWebView2Async(env);var settings=web.CoreWebView2.Settings;settings.AreDevToolsEnabled=false;settings.AreDefaultContextMenusEnabled=false;settings.IsStatusBarEnabled=false;web.CoreWebView2.SetVirtualHostNameToFolderMapping("shixun.local",Path.Combine(root,"ui"),CoreWebView2HostResourceAccessKind.DenyCors);web.CoreWebView2.NavigationStarting+=delegate(object s,CoreWebView2NavigationStartingEventArgs e){if(e.Uri!=Home)e.Cancel=true;};web.CoreWebView2.NewWindowRequested+=delegate(object s,CoreWebView2NewWindowRequestedEventArgs e){e.Handled=true;};web.CoreWebView2.PermissionRequested+=delegate(object s,CoreWebView2PermissionRequestedEventArgs e){e.State=CoreWebView2PermissionState.Deny;};web.CoreWebView2.WebMessageReceived+=OnMessage;web.CoreWebView2.AddWebResourceRequestedFilter("https://images.shixun.local/image/*",CoreWebView2WebResourceContext.Image);web.CoreWebView2.WebResourceRequested+=ImageRequested;web.CoreWebView2.Navigate(Home);}catch{MessageBox.Show("阅读界面加载失败，请安装或修复 Microsoft Edge WebView2 Runtime。","拾讯");}showing=false;}
 async void ImageRequested(object sender,CoreWebView2WebResourceRequestedEventArgs e){var deferral=e.GetDeferral();try{var parts=new Uri(e.Request.Uri).AbsolutePath.Split('/');int index;if(parts.Length!=4||!int.TryParse(parts[3],out index))throw new Exception();var bytes=await ImageBytes(parts[2],index);e.Response=web.CoreWebView2.Environment.CreateWebResourceResponse(new MemoryStream(bytes),200,"OK","Content-Type: "+(bytes[0]==0x89?"image/png":bytes[0]==0xff?"image/jpeg":bytes[0]==0x47?"image/gif":"image/webp")+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff");}catch{e.Response=web.CoreWebView2.Environment.CreateWebResourceResponse(new MemoryStream(new byte[0]),404,"Unavailable","Cache-Control: no-store");}finally{deferral.Complete();}}
 public Task<byte[]> ImageBytes(string id,int index){return ImageCache.Get(id+":"+index,()=>Task.Run(()=>{Article article;Source source;RequestProfile profile;lock(store.Gate){var found=store.State.articles.FirstOrDefault(a=>a.id==id);if(found==null||index<0||index>=found.images.Count)throw new SafeError("图片不存在。");article=Data.Clone(found);source=store.State.sources.FirstOrDefault(s=>s.id==article.source);RequestProfile original;profile=source!=null&&store.State.credentials.TryGetValue(source.id,out original)?Data.Clone(original):new RequestProfile();}Uri image=Transport.ValidateUrl(article.images[index]);if(source==null||!SameOrigin(image,Transport.ValidateUrl(source.url)))profile=new RequestProfile();profile.method="GET";profile.body="";profile.fields.RemoveAll(f=>f.place=="form"||f.place=="path");if(source!=null&&source.imageReferer.Length>0)profile.fields.Add(new RequestField{place="header",name="Referer",value=source.imageReferer});var result=Transport.Fetch(image.AbsoluteUri,profile,"","",8*1024*1024);var bytes=result.bytes;if(bytes==null||bytes.Length<12||!(bytes[0]==0x89&&bytes[1]==0x50||bytes[0]==0xff&&bytes[1]==0xd8||bytes[0]==0x47&&bytes[1]==0x49||bytes[0]==0x52&&bytes[1]==0x49))throw new SafeError("非支持的图片格式。");return bytes;}));}
 static bool SameOrigin(Uri a,Uri b){return a.Scheme==b.Scheme&&a.Host==b.Host&&a.Port==b.Port;}
 void MarkNoticeRead(string id){lock(store.Gate){var article=store.State.articles.FirstOrDefault(a=>a.id==id);if(article==null)return;article.read=true;article.remindAt=0;store.Save();}Push();}
 async void OnTick(object sender,EventArgs e){try{string signal=Path.Combine(store.Folder,"show.signal");if(File.Exists(signal)){File.Delete(signal);ShowReader();}if(File.Exists(Path.Combine(store.Folder,"exit.signal"))){File.Delete(Path.Combine(store.Folder,"exit.signal"));ExitThread();return;}ShowStartupSummary();CheckPush();DrainNotifications();if(!engine.Busy&&Data.Now()-lastClean>60000){store.Clean();ImageCache.ClearExpired();lastClean=Data.Now();if(web!=null&&web.CoreWebView2!=null)await web.CoreWebView2.Profile.ClearBrowsingDataAsync(CoreWebView2BrowsingDataKinds.DiskCache);Push();}if(!engine.Busy&&engine.HasDue())await engine.Run();}catch{store.Log("maintenance failed");}}
 void Push(){if(!ready||web==null||web.CoreWebView2==null||web.Source==null||web.Source.AbsoluteUri!=Home)return;lock(store.Gate){var sourceDtos=store.State.sources.Select(s=>new{id=s.id,name=s.name,url=s.url,group=s.group,enabled=s.enabled,privateSource=s.privateSource||store.State.credentials.ContainsKey(s.id),interval=s.interval,error=s.error,lastSync=s.lastSync,nextRun=s.nextRun,upstreamUpdated=s.upstreamUpdated,stale=s.upstreamUpdated>0&&Data.Now()-s.upstreamUpdated>900000,imageReferer=s.imageReferer,initialized=s.initialized,configured=store.State.credentials.ContainsKey(s.id)}).ToArray();var rules=store.State.ruleSources.Select(s=>new{id=s.id,name=s.name,url=s.url,autoUpdate=s.autoUpdate,error=s.error,lastSync=s.lastSync,configured=store.State.credentials.ContainsKey(s.id)}).ToArray();var articles=store.State.articles.OrderByDescending(a=>a.time).Take(20000).Select(a=>new{id=a.id,source=a.source,title=a.title,summary=a.summary,html=a.html,link=a.link,author=a.author,time=a.time,firstSeen=a.firstSeen,dateOrigin=a.dateOrigin,category=a.category,read=a.read,star=a.star,locked=a.locked,remindAt=a.remindAt,ai=a.ai,aiError=a.aiError,images=a.images.Select((x,i)=>"https://images.shixun.local/image/"+a.id+"/"+i).ToArray()}).ToArray();web.CoreWebView2.PostWebMessageAsJson(Data.Json().Serialize(new{type="state",settings=store.State.settings,sources=sourceDtos,ruleSources=rules,categories=store.State.categories,articles=articles,notices=store.State.notices,busy=engine.Busy,recovery=store.Recovery,ai=store.State.ai??new AiSettings(),digest=store.State.digest,aiDaily=AiService.DailyUsage(store.State,DateTime.Now),aiHistory=store.State.aiHistory.OrderByDescending(x=>x.at).Take(200).ToArray(),update=updateInfo,currentVersion=UpdateService.Current,aiUsage=new{input=store.State.aiInputTokens,output=store.State.aiOutputTokens,total=store.State.aiTotalTokens},aiConfigured=store.State.credentials.ContainsKey(AiService.CredentialKey),aiRequestsToday=store.State.aiDay==DateTime.Now.ToString("yyyy-MM-dd")?store.State.aiRequestsToday:0}));}}
 async void OnMessage(object sender,CoreWebView2WebMessageReceivedEventArgs args){if(args.Source!=Home)return;Dictionary<string,object> message=null;string request="";try{if(args.WebMessageAsJson.Length>2*1024*1024)throw new SafeError("请求过大。");message=Data.Json().Deserialize<Dictionary<string,object>>(args.WebMessageAsJson);request=S(message,"request");string action=S(message,"action");object payload;message.TryGetValue("payload",out payload);var data=payload as Dictionary<string,object>??new Dictionary<string,object>();var result=await Dispatch(action,data);if(request.Length>0)Reply(request,true,result,null);}catch(Exception ex){if(request.Length>0)Reply(request,false,null,ex is SafeError?ex.Message:"操作失败，请重试；私人配置未写入日志。");store.Log("ui operation failed");}Push();}
 void Reply(string request,bool ok,object result,string error){if(ready&&web!=null&&web.CoreWebView2!=null)web.CoreWebView2.PostWebMessageAsJson(Data.Json().Serialize(new{type="reply",request=request,ok=ok,result=result,error=error}));}
 static string S(Dictionary<string,object>d,string key){object x;return d.TryGetValue(key,out x)&&x!=null?Convert.ToString(x):"";}
 static T ConvertData<T>(object value){return Data.Json().Deserialize<T>(Data.Json().Serialize(value));}
 void Open(string url){Uri uri=Transport.ValidateUrl(url);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(uri.AbsoluteUri){UseShellExecute=true});}
 void Notify(List<Article> articles,bool test){if(test){if(articles.Count>0)NotifySingle(new List<Article>{articles[0]},true);return;}if(WaitForAiNotices(articles))return;notificationQueue.Add(articles);DrainNotifications();}
 void DrainNotifications(){if(exiting||locked||pauseUntil>Data.Now())return;Preferences prefs;lock(store.Gate)prefs=Data.Clone(store.State.settings);if(prefs.notification=="off"||Rules.Quiet(prefs,DateTime.Now)||!Popup.Allowed())return;while(notificationQueue.Count>0&&popups.Count<2){if(prefs.notification=="system"&&nextSystemNotice>Data.Now())return;string id=notificationQueue.Take();Article article;lock(store.Gate){var saved=store.State.articles.FirstOrDefault(a=>a.id==id);article=saved==null?null:Data.Clone(saved);}if(article!=null&&!article.read){lock(store.Gate){if(Rules.NeedsAiNotice(store.State)&&(article.ai==null||article.aiError.Length>0||article.ai.fingerprint!=AiService.Fingerprint(article,store.State.ai,store.State.categories))){notificationQueue.Complete(id);WaitForAiNotices(new List<Article>{article});continue;}if(!Rules.Notify(store.State,article)){notificationQueue.Complete(id);continue;}}}if(article==null||article.read){notificationQueue.Complete(id);continue;}NotifySingle(new List<Article>{article},false);if(prefs.notification=="system"){nextSystemNotice=Data.Now()+Math.Max(10,prefs.duration)*1000;notificationQueue.Complete(id);return;}}}
 void LayoutPopups(){int offset=20;for(int i=0;i<popups.Count;i++){var popup=popups[i];if(popup.IsDisposed)continue;var area=Screen.FromPoint(Cursor.Position).WorkingArea;popup.Location=new Point(store.State.settings.position=="left"?area.Left+20:area.Right-popup.Width-20,area.Bottom-popup.Height-offset);offset+=popup.Height+12;}}
 void NotifySingle(List<Article> articles,bool test){if(articles.Count==0)return;Preferences prefs;lock(store.Gate)prefs=Data.Clone(store.State.settings);if(prefs.notification=="off")return;var article=Data.Clone(articles.First());article.title=store.State.ai!=null&&(store.State.ai.useTitle||store.State.ai.notifyAfter)&&article.ai!=null?AiService.DisplayTitle(article.ai,store.State.ai.useRating):Feeds.ShortTitle(article.title);var source=store.State.sources.FirstOrDefault(s=>s.id==article.source);string name=test?"拾讯 · 通知预览":source==null?"订阅更新":source.name;if(prefs.notification=="system"){tray.BalloonTipTitle=Data.Limit(article.title,60);tray.BalloonTipText=Data.Limit(article.summary,180);tray.ShowBalloonTip(prefs.duration*1000);return;}var popup=new Popup(name,article,prefs,()=>{ShowReader();if(ready)web.CoreWebView2.PostWebMessageAsJson(Data.Json().Serialize(new{type="select",id=article.id}));},()=>{if(article.link.Length>0)Open(article.link);},()=>{lock(store.Gate){var a=store.State.articles.FirstOrDefault(x=>x.id==article.id);if(a!=null){a.remindAt=Data.Now()+900000;store.Save();Push();}}},()=>MarkNoticeRead(article.id),()=>ImageBytes(article.id,0));var area=Screen.FromPoint(Cursor.Position).WorkingArea;popup.StartPosition=FormStartPosition.Manual;popup.Location=new Point(prefs.position=="left"?area.Left+20:area.Right-popup.Width-20,area.Bottom-popup.Height-20-popups.Count*(popup.Height+12));popups.Add(popup);popup.FormClosed+=delegate{popups.Remove(popup);if(!test)notificationQueue.Complete(article.id);LayoutPopups();if(!exiting)UI(DrainNotifications);};popup.Show();LayoutPopups();}
 protected override void ExitThreadCore(){exiting=true;timer.Stop();timer.Dispose();Microsoft.Win32.SystemEvents.SessionSwitch-=OnSession;foreach(var p in popups.ToArray())p.Close();tray.Visible=false;tray.Dispose();store.Save();if(window!=null)window.Dispose();try{File.Delete(Path.Combine(store.Folder,"app.pid"));}catch{}base.ExitThreadCore();}
